Method.Implementation:
	Set tStatus = $$$OK
	Try {
	
		Set tStatus = ..Log(.pLogFile,..%ClassName(1),"PurgeQueue","Begin purging queue " _ pQueueName) $$$ThrowOnError(tStatus)
		
		// SQLPROC Ens.Queue_EnumerateItem to read all items in a queue
		Set tCall = "Call Ens.Queue_EnumerateItem(?)"
		Set tSQLStatement = ##class(%SQL.Statement).%New()
  		Set tStatus = tSQLStatement.%Prepare(tCall)
  		$$$ThrowOnError(tStatus)
  		Set tResultSet = tSQLStatement.%Execute(pQueueName)
  		
  		Set tAbortedQueueItems= 0, tTotalQueueItems = 0
  		While tResultSet.%Next(.tStatus) {
  			$$$ThrowOnError(tStatus)
  			Set tTotalQueueItems = tTotalQueueItems + 1
  			
  			Set tForcePurge = 0, tDiff = 0
  			
  			Set tPriority = tResultSet.%Get("Priority")
	  		Set tIndex = tResultSet.%Get("Index")
	  		Set tMessageId = tResultSet.%Get("MessageId")
	  		
	  		Set tMessageHeader = ##class(Ens.MessageHeader).%OpenId(tMessageId,,.tStatus)
	  		If (($System.Status.GetErrorCodes(tStatus) [ "5809") || ($System.Status.GetErrorCodes(tStatus) [ "5813")) {
		  		Set tForcePurge = 1	// Can't find header so force it to purge
		  		Set tStatus = $$$OK
	  		} Else {
	  			$$$ThrowOnError(tStatus)
	  		}
	  		
	  		If ($$$IsdefObject(tMessageHeader)) {
		  		Set tCreatedOn = ##class(Ens.DataType.UTC).timeUTCtoLocal(tMessageHeader.TimeCreated)
		  		Set tDiff = $System.SQL.DATEDIFF("d",tCreatedOn,$ZDT($H,3))
	  		}
	  		;No need to loop through, if the first message of the queue has created within the the Days to keep
	  		Quit:(tTotalQueueItems=1)&&(tDiff <= pDaysToKeep)
	  		
	  		If ((tDiff > pDaysToKeep) || tForcePurge) {
	  			
	  			// Log the item we are aborting
	  			//Set tStatus = ..Log(.tLogFile,..%ClassName(1),"PurgeQueue","Queue item to abort: " _ tPriority _ "|" _ tIndex _ "|" _ tMessageId) $$$ThrowOnError(tStatus)
	  			
	  			// Abort item
	  			If (pDoAbort) {
	  				Set tStatus = ##class(Ens.Queue).AbortItem(pQueueName,tPriority,tIndex)
	  				If ($$$ISERR(tStatus)) {
	  					Set tStatus = $$$OK
	  					CONTINUE
	  				}
	  				//$$$ThrowOnError(tStatus)
	  				//Set tStatus = ..Log(.tLogFile,..%ClassName(1),"PurgeQueue","Aborted queue item successfully") $$$ThrowOnError(tStatus)
	  			}
	  			Set tAbortedQueueItems = tAbortedQueueItems + 1
	  		}
  		}
  		$$$ThrowOnError(tStatus)
  		
  		Set tStatus = ..Log(.pLogFile,..%ClassName(1),"PurgeQueue","Finished purging queue " _ pQueueName _ " (Aborted:" _ tAbortedQueueItems _ "|Total:" _ tTotalQueueItems _ ")") $$$ThrowOnError(tStatus)
  		
	} Catch eException {
		Set tStatus = eException.AsStatus()
		Set tErrorMessage = $System.Status.GetErrorText(tStatus)
		Do ..Log(.pLogFile,..%ClassName(1),"PurgeQueue","Failed to completely purge queue: " _ tErrorMessage)
	}
	Quit tStatus

	#Dim tSQLStatement As %SQL.Statement
	#Dim tResultSet As %SQL.StatementResult
	
	
	Set tStatus = $$$OK
	Try {
		If (pQueueName = "") { $$$ThrowStatus($$$ERROR($$$GeneralError, "pQueueName is required.")) }
		
		Do ..Log(.pLogFile,$Classname(),"AbortOrphanedItems","Abort Orphaned Items Start")

		Kill ^ITF.Util.QueueItems
		
		// SQLPROC Ens.Queue_EnumerateItem to read all items in a queue
		Set tCall = "Call Ens.Queue_EnumerateItem(?)"
		Set tSQLStatement = ##class(%SQL.Statement).%New()
  		Set tStatus = tSQLStatement.%Prepare(tCall)
  		$$$ThrowOnError(tStatus)
  		Set tResultSet = tSQLStatement.%Execute(pQueueName)
  		
  		Set tAbortedQueueItems= 0, tTotalQueueItems = 0, tInvalidQueueItems = 0 , tValidQueueItems = 0
  		While tResultSet.%Next(.tStatus) {
  			$$$ThrowOnError(tStatus)
	  		
	  		Set ^ITF.Util.QueueItems("TotalQueueItems") = $GET(^ITF.Util.QueueItems("TotalQueueItems"),0) + 1
	  		
	  		Set tPriority = tResultSet.%Get("Priority")
	  		Set tIndex = tResultSet.%Get("Index")
	  		Set tMessageId = tResultSet.%Get("MessageId")
	  		Set ^ITF.Util.QueueItems("QueueItems",tIndex) = tMessageId _ "|" _ tPriority
	  		
	  		Set tIsValid = ..IsValidQueueItem(tMessageId,.tStatus)
	  		$$$ThrowOnError(tStatus)
	  		
	  		If ('tIsValid) {
		  		Set ^ITF.Util.QueueItems("InvalidQueueItems") = $GET(^ITF.Util.QueueItems("InvalidQueueItems"),0) + 1
		  		If (pAbort) {
		  			// Add item to the aborted list
		  			Set ^ITF.Util.QueueItems("AbortedQueueItems",tIndex) = tPriority
		  		}
	  		} Else {
		  		Set ^ITF.Util.QueueItems("ValidQueueItems") = $GET(^ITF.Util.QueueItems("ValidQueueItems"),0) + 1
	  		}
  		}
  		$$$ThrowOnError(tStatus)
  		
  		If (pAbort) {
			Set tStatus = ..AbortQueueItems()
			$$$ThrowOnError(tStatus)
  		}
  		
  		Do ..Log(.pLogFile,$Classname(),"AbortOrphanedItems","Total Queue Items: " _ $GET(^ITF.Util.QueueItems("TotalQueueItems"),0))
  		Do ..Log(.pLogFile,$Classname(),"AbortOrphanedItems","Valid Queue Items: " _ $GET(^ITF.Util.QueueItems("ValidQueueItems"),0))
		Do ..Log(.pLogFile,$Classname(),"AbortOrphanedItems","Invalid Queue Items: " _ $GET(^ITF.Util.QueueItems("InvalidQueueItems"),0))
		Do ..Log(.pLogFile,$Classname(),"AbortOrphanedItems","Aborted Queue Items: " _ $GET(^ITF.Util.QueueItems("AbortedQueueItems"),0))
		Do ..Log(.pLogFile,$Classname(),"Abort Orphaned Items")
		
	} Catch eException {
		Set tStatus = eException.AsStatus()
		Lock -^Ens.Queue(pQueueName)
	}
	Quit tStatus

	Set tIsValid = 0
	Try {
		Set SQLCODE = ""
  		&sql(SELECT %Id FROM Ens.MessageHeader WHERE %Id = :pMessageId)
  		If ((SQLCODE '= 0) && (SQLCODE '= 100)) {
	  		$$$ThrowStatus($$$ERROR($$$SQLError, "Ens.MessageHeader lookup failed for tMessageId: " _ tMessageId))	
  		} ElseIf (SQLCODE = 0) {
	  		Set tIsValid = 1	
  		}
	} Catch eException {
		Set pStatus = eException.AsStatus()
	}
	Quit tIsValid

	Set tStatus = $$$OK
	Lock +^Ens.Queue(pQueueName)
	Try {
		If ('##class(EnsPortal.Utils).CheckResourceList("%Ens_Queues:WRITE")) {
			$$$ThrowStatus($$$ERROR($$$InsufficientPrivilegeForOperation))
  		}
	
		Set tIndex = $ORDER(^ITF.Util.QueueItems("AbortedQueueItems",""))
		While tIndex '= "" {
			Set tPriority = $PIECE(^ITF.Util.QueueItems("AbortedQueueItems",tIndex),"|",2)
			
			Set tStatus = ##class(Ens.Queue).AbortItem(pQueueName,tPriority,tIndex)
  			$$$ThrowOnError(tStatus)
			
			Set ^ITF.Util.QueueItems("AbortedQueueItems") = $GET(^ITF.Util.QueueItems("AbortedQueueItems"),0) + 1

			Set tIndex = $ORDER(^ITF.Util.QueueItems("AbortedQueueItems",tIndex))
		}
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	
	Lock -^Ens.Queue(pQueueName)
	Quit tStatus

	#Dim tSQLStatement As %SQL.Statement
	#Dim tResultSet As %SQL.StatementResult
	
	// @TODO: Make this dynamic***
	Set tQueueName = "Cern-Adt-Hl7_Legacy"
	// @TODO: Make this dynamic***
	Set tQuery = 	"SELECT %Id " _
					"FROM Ens.MessageHeader " _
					"WHERE %Id IN ('96643617','96643621','96643726')"
	
	Set tStatus = $$$OK
	Try {
		If ('##class(EnsPortal.Utils).CheckResourceList("%Ens_Queues:WRITE")) {
			$$$ThrowStatus($$$ERROR($$$InsufficientPrivilegeForOperation))
  		}
  		
		Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","Process started")
		
		Set tSQLStatement = ##class(%SQL.Statement).%New()
  		Set tStatus = tSQLStatement.%Prepare(tQuery)
  		$$$ThrowOnError(tStatus)
  		Set tResultSet = tSQLStatement.%Execute()
		
		Lock +$$$EnsQueue(tQueueName)
		
		Set tMsgCount = 0
		While tResultSet.%Next(.tStatus) {
  			$$$ThrowOnError(tStatus)
			Set tMessageHeaderId = tResultSet.%GetData(1)
			Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","MH %Id: " _ tMessageHeaderId)
			
			// Look this up in the queue
			Set tIndex = "", tPriority = 6
			For {
				Set tIndex = $ORDER($$$EnsQueue(tQueueName,tPriority,tIndex))
				Quit:(tIndex = "")
				
				Set tMessageHeaderIdFromQueue = $$$EnsQueue(tQueueName,tPriority,tIndex)
				
				If (tMessageHeaderId = tMessageHeaderIdFromQueue) {
					Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","Found queue item. Index:" _ tIndex _ "|MsgHeaderId:" _  tMessageHeaderIdFromQueue)
				
					If (pDeQueueAndSuspend) {
						Kill $$$EnsQueue(tQueueName,tPriority,tIndex)
						Set $$$EnsQueue(tQueueName,0,"count") = $$$EnsQueue(tQueueName,0,"count")-1
					}
					Set tRequestHeader = ##class(Ens.MessageHeader).%OpenId(tMessageHeaderIdFromQueue,,.tStatus)
					$$$ThrowOnError(tStatus)
					
					If (tRequestHeader '= $$$NULLOREF) {
						If (pDeQueueAndSuspend) {
							Do tRequestHeader.SetStatus($$$eMessageStatusSuspended)
						}
						Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","Message '" _ tMessageHeaderIdFromQueue _ "' in queue '"_tQueueName_"' has been marked as suspended.")
						Set tMsgCount = tMsgCount + 1
						Quit
					}
					Kill tRequestHeader
				}
			}
		}
		$$$ThrowOnError(tStatus)
		
		Lock -$$$EnsQueue(tQueueName)
		
		Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","Total messages processed: " _ tMsgCount)
		
		Do ..Log(.pLogFile,$Classname(),"SuspendAndDeQueueByQuery","Process ended")
	} Catch eException {
		Set tStatus = eException.AsStatus()
		Lock -$$$EnsQueue(tQueueName)	
	}
	Quit tStatus

Set tStatus = $$$OK
Try {
	
	// For each interface namespace on this instance, setup a purge task to run in 15 min increments starting at the specified hour
	
	// Run for all namespaces
	Set tStatus = ..GetEnvironment(.tEnvironment,.tInstanceType,.tInstanceName)
	$$$ThrowOnError(tStatus)
	
	// Don't init tasks in prod or for msgbk
	Quit:(tEnvironment = "PROD")
	Quit:(tInstanceType = "MSGBK")
	
	// Loop through namespace list
	Set tQuery = "SELECT DISTINCT Namespace FROM IHC_EAI_System_Data.Namespace WHERE EnvironmentType = ? AND InstanceName = ?"
	Set tStatement = ##class(%SQL.Statement).%New()
	Set tStatus = tStatement.%Prepare(tQuery)
	$$$ThrowOnError(tStatus)
	Set tResultSet = tStatement.%Execute(tEnvironment,tInstanceName)
	
	Set tStartTime = $PIECE($System.SQL.DATEADD("d",1,$ZDT($H,3))," ",1) _ " " _ "04:00:00"
	While (tResultSet.%Next(.tStatus)) {
		$$$ThrowOnError(tStatus)
		
		Set tNamespace = tResultSet.%GetData(1)
	
		Set tStatus = ..CreateTask(tNamespace,pDaysToKeep,tStartTime)
		$$$ThrowOnError(tStatus)
		
		// Add 15 minutes
		Set tStartTime = $System.SQL.DATEADD("mi",15,tStartTime)
	}
	$$$ThrowOnError(tStatus)
	
	
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

Set tStatus = $$$OK Try {
New $NAMESPACE Set $NAMESPACE = "%SYS"
Set tTaskName = "Purge " _ pNamespaceName _ " Queues" Set SQLCODE = "", tCount = 0 &sql(SELECT COUNT(*) INTO :tCount FROM %SYS.Task WHERE Name = :tTaskName)
If (tCount = 0) { // If doesn't already exist, create Set tTask = ##class(%SYS.Task).%New() Set tTask.Name = tTaskName Set tTask.TaskClass = "IHC.EAI.Queue.Task.PurgeQueues" Set tTask.Description = "Purge queues in the " _ pNamespaceName _ " namespace" Set tTask.NameSpace = pNamespaceName Set tTask.TimePeriod = 0 Set tTask.DailyStartTime = $ZTIMEH($PIECE(pStartTime," ",2)) Set tTaskDef = ##class(IHC.EAI.Queue.Task.PurgeQueues).%New() Set tTaskDef.DaysToKeep = pDaysToKeep Set tStatus = tTask.AssignSettings(tTaskDef) $$$ThrowOnError(tStatus) Set tStatus = tTask.%Save() $$$ThrowOnError(tStatus) }
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus
